import { PatientCase, GeneratedCaseReport } from '../types/case';
import { SYMPTOM_CATEGORIES, SYMPTOM_FOLLOWUP_QUESTIONS } from '../data/symptomQuestions';
import { SUPPORTED_LANGUAGES } from '../data/translations';

export const reportService = {
  /**
   * Synthesizes a structured 13-section Case Report directly from the patient's collected data.
   * NOTE: This is generated by frontend rule logic as a simulated AI summary.
   */
  generateReportFromCase(patientCase: Partial<PatientCase>): GeneratedCaseReport {
    const languageObj = SUPPORTED_LANGUAGES.find((l) => l.code === patientCase.language);
    const langDisplay = languageObj ? `${languageObj.name} (${languageObj.nativeName})` : 'English';

    // 1. Patient info
    const patientName = patientCase.patientName || 'Patient';
    const demoId = patientCase.id ? `MC-${patientCase.id.slice(-6).toUpperCase()}` : 'PENDING';

    // 2. Identify primary symptoms names
    const primarySymptomIds = patientCase.primarySymptoms || [];
    const symptomNames = primarySymptomIds.map((id) => {
      const match = SYMPTOM_CATEGORIES.find((cat) => cat.id === id);
      return match ? match.name : id;
    });

    const chiefComplaint =
      symptomNames.length > 0
        ? `Patient presents with ${symptomNames.join(', ')} reported through voice/guided questionnaire.`
        : 'Health discomfort requiring medical evaluation.';

    // 3. Extract duration & severity
    const answers = patientCase.symptomAnswers || {};
    const severityScore = answers.shared_severity || 5;
    let severityLabel = 'Moderate';
    if (severityScore <= 3) severityLabel = 'Mild';
    else if (severityScore >= 7) severityLabel = 'Severe';

    const durationRaw = answers.shared_duration || answers.fever_duration || answers.cough_duration || 'few days';
    const durationFormatted = typeof durationRaw === 'string' ? durationRaw.replace(/_/g, ' ') : 'Recent onset';

    // 4. Construct HPI (History of Present Illness) narrative
    const hpiSentences: string[] = [];
    hpiSentences.push(
      `Patient communicates in ${langDisplay} and completed the guided case-taking workflow.`
    );
    hpiSentences.push(
      `Primary health concern centers around ${symptomNames.join(' alongside ')}, with symptom severity rated as ${severityScore}/10 (${severityLabel}).`
    );

    if (answers.shared_progression) {
      hpiSentences.push(
        `Progression status: Patient notes condition is "${String(answers.shared_progression).replace(/_/g, ' ')}".`
      );
    }
    if (answers.shared_prior_episodes) {
      hpiSentences.push(
        `Recurrence: ${answers.shared_prior_episodes === 'yes' ? 'Patient had similar episodes previously.' : 'No prior history of identical symptom episode reported.'}`
      );
    }
    if (answers.shared_relief_triggers) {
      hpiSentences.push(
        `Self-reported relieving or aggravating factors: "${answers.shared_relief_triggers}".`
      );
    }

    // Add specific symptom details if available
    if (answers.fever_temperature) {
      hpiSentences.push(`Temperature check: Reported as ${String(answers.fever_temperature).replace(/_/g, ' ')}.`);
    }
    if (answers.cough_type) {
      hpiSentences.push(`Cough characteristics: Patient notes "${String(answers.cough_type).replace(/_/g, ' ')}".`);
    }
    if (answers.stomach_location) {
      hpiSentences.push(`Abdominal pain localization: ${String(answers.stomach_location).replace(/_/g, ' ')}.`);
    }

    // 5. Associated symptoms list
    const associated: string[] = [];
    Object.entries(answers).forEach(([key, val]) => {
      if (Array.isArray(val)) {
        val.forEach((item) => {
          if (item !== 'none') associated.push(item.replace(/_/g, ' '));
        });
      }
    });
    if (associated.length === 0) {
      associated.push('No secondary systemic symptoms flagged by patient');
    }

    // 6. Medical history
    const history = patientCase.medicalHistory;
    const historyText =
      history && history.conditions && history.conditions.length > 0
        ? history.conditions.join(', ')
        : history?.provided === false
        ? 'Information not provided / skipped by patient'
        : 'None reported by patient';

    const medsText = history?.medications?.trim()
      ? history.medications
      : history?.provided === false
      ? 'Information not provided / skipped'
      : 'None reported';

    const allergiesText = history?.allergies?.trim()
      ? history.allergies
      : history?.provided === false
      ? 'Information not provided / skipped'
      : 'No known drug or environmental allergies reported';

    // 7. Reports metadata
    const reportsList = (patientCase.uploadedReports || []).map((rep) => ({
      name: rep.name,
      type: rep.type || (rep.name.endsWith('.pdf') ? 'application/pdf' : 'image/jpeg'),
      sizeFormatted: `${(rep.size / (1024 * 1024)).toFixed(1)} MB`,
      extractionNote: rep.isImage
        ? 'Medical prescription or diagnostic image attached for optical analysis and clinician verification.'
        : 'Uploaded PDF document attached for automated clinical analysis and clinician verification.',
    }));

    // 8. Patient-reported items
    const patientReported = [
      `Self-assessed pain/distress score: ${severityScore}/10 (${severityLabel})`,
      `Chief complaint: ${symptomNames.join(', ')}`,
      `Estimated timeline: ${durationFormatted}`,
    ];
    if (answers.shared_relief_triggers) {
      patientReported.push(`Patient observation: ${answers.shared_relief_triggers}`);
    }

    // 9. Missing or Unanswered items
    const missing: string[] = [];
    if (!history?.provided) {
      missing.push('Detailed medical history was skipped or unrecorded during intake');
    }
    if (!answers.shared_relief_triggers) {
      missing.push('Specific relieving or exacerbating factors not specified');
    }
    if (!patientCase.uploadedReports || patientCase.uploadedReports.length === 0) {
      missing.push('No previous physical or diagnostic laboratory reports attached');
    }

    // 10. Items requiring doctor review
    const doctorReviewItems: string[] = [
      'Correlate patient-reported severity score with clinical physical examination',
      'Verify patient medication compliance and cross-check for potential drug interactions',
      'Confirm stability of vital signs (temperature, pulse, BP, SpO2)',
    ];

    if (primarySymptomIds.includes('chest_discomfort') || primarySymptomIds.includes('breathing_difficulty')) {
      doctorReviewItems.unshift(
        'PRIORITY SAFETY CHECK: Cardiopulmonary evaluation for reported chest or respiratory distress'
      );
    }
    if (primarySymptomIds.includes('fever')) {
      doctorReviewItems.push('Consider blood smear / rapid tests for acute febrile illness');
    }

    return {
      patientInfo: {
        name: patientName,
        demoId,
        age: patientCase.patientAge || 45,
        gender: patientCase.patientGender || 'Female',
      },
      selectedLanguage: langDisplay,
      chiefComplaint,
      historyOfPresentIllness: hpiSentences.join(' '),
      symptomDurationAndSeverity: `Timeline: ${durationFormatted}. Severity index: ${severityScore}/10 (${severityLabel}).`,
      associatedSymptoms: associated,
      relevantMedicalHistory: historyText,
      currentMedicines: medsText,
      knownAllergies: allergiesText,
      previousMedicalReports: reportsList,
      patientReportedInformation: patientReported,
      missingOrUnansweredInformation: missing.length > 0 ? missing : ['All questionnaire sections completed by patient'],
      itemsRequiringDoctorReview: doctorReviewItems,
      generatedAt: new Date().toISOString(),
      isDemoGenerated: false,
    };
  },
};
